test23ExhaustedTurboDoesNotIncreaseTheMaximumSpeed

	| aCar |

	aCar _ self carReadyToOvertake.

	aCar
		activateTurbo; deactivateTurbo;
		activateTurbo; deactivateTurbo;
		activateTurbo; deactivateTurbo;
		activateTurbo.

	self assert: aCar isTurboActivated.
	self assert: aCar speed equals: 100 * kilometer / hour

test23ExhaustedTurboDoesNotIncreaseTheMaximumSpeed

	| aCar |

	aCar _ self carReadyToOvertake.

	aCar
		activateTurbo; deactivateTurbo;
		activateTurbo; deactivateTurbo;
		activateTurbo; deactivateTurbo;
		activateTurbo.

	self assert: aCar isTurboActivated.
	self assert: aCar speed equals: 100 * kilometer / hour
